namespace CheckoutPricing.Domain;

public static class LoyaltyDiscount
{
    private const int CeilingPoints = 10;

    public static int PayableCents(LoyaltyTier tier, int subtotalCents)
    {
        var points = Math.Min(BaseRate(tier) + OrderSizeBonus(subtotalCents), CeilingPoints);
        var discountCents = subtotalCents * points / 100;

        return subtotalCents - discountCents;
    }

    private static int BaseRate(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 7,
        LoyaltyTier.Gold => 9
    };

    private static int OrderSizeBonus(int subtotalCents) => subtotalCents switch
    {
        >= 20000 => 3,
        >= 5000 => 1,
        _ => 0
    };
}
E
python3 - <<'E'
p='src/CheckoutPricing.Application/CalculatePayableTotal.cs'
s=open(p).read().replace("return subtotalCents;","return LoyaltyDiscount.PayableCents(tier, subtotalCents);")
open(p,'w').write(s)
E
dotnet test 2>&1 | grep -E "error|warn|Passed!|Failed!"; git status --short

